2646	/**
2647	 * Parse a size token (nginx `64m`, PHP `128M`, a bare Apache `LimitRequestBody`
2648	 * byte count) into whole megabytes. A unit-less value is treated as bytes, which
2649	 * is what `LimitRequestBody` emits; k/m/g are honoured case-insensitively.
2650	 * Returns 0 for anything unparseable. (FIX A4)
2651	 */
2652	function sizeToMb(v: string): number {
2653	  const m = /^\s*(\d+)\s*([kKmMgG])?/.exec(String(v ?? ""));
2654	  if (!m) return 0;
2655	  const n = Number(m[1]);
2656	  if (!Number.isFinite(n) || n < 0) return 0;
2657	  switch ((m[2] ?? "").toLowerCase()) {
